CREATE TABLE clock_observations (
    receiver_instance_id BLOB NOT NULL CHECK (length(receiver_instance_id) = 16),
    observation_sequence INTEGER NOT NULL CHECK (observation_sequence BETWEEN 0 AND 9223372036854775807),
    clock_state_generation INTEGER NOT NULL CHECK (clock_state_generation BETWEEN 0 AND 9223372036854775807),
    sampled_at_monotonic_us INTEGER NOT NULL CHECK (sampled_at_monotonic_us BETWEEN 0 AND 9223372036854775807),
    sampled_at_utc_us INTEGER CHECK (sampled_at_utc_us IS NULL OR sampled_at_utc_us BETWEEN -9223372036854775808 AND 9223372036854775807),
    step_discontinuity_boundary INTEGER NOT NULL CHECK (step_discontinuity_boundary IN (0, 1)),
    system_time_quality_id INTEGER NOT NULL,
    rtc_health_id INTEGER NOT NULL,
    PRIMARY KEY (receiver_instance_id, observation_sequence),
    FOREIGN KEY (receiver_instance_id) REFERENCES receiver_instances(receiver_instance_id),
    FOREIGN KEY (system_time_quality_id) REFERENCES system_time_quality_codes(id),
    FOREIGN KEY (rtc_health_id) REFERENCES rtc_health_codes(id)
) STRICT, WITHOUT ROWID;

