END;

CREATE TABLE diagnostics (
    receiver_instance_id BLOB NOT NULL CHECK (length(receiver_instance_id) = 16),
    diagnostic_sequence INTEGER NOT NULL CHECK (diagnostic_sequence BETWEEN 0 AND 9223372036854775807),
    sampled_at_monotonic_us INTEGER NOT NULL CHECK (sampled_at_monotonic_us BETWEEN 0 AND 9223372036854775807),
    severity_id INTEGER NOT NULL,
    error_domain_id INTEGER NOT NULL,
    operation_id INTEGER NOT NULL,
    error_code_id INTEGER NOT NULL CHECK (error_code_id BETWEEN 0 AND 65535),
    context_schema_id INTEGER NOT NULL CHECK (context_schema_id BETWEEN 0 AND 255),
    context_length INTEGER NOT NULL CHECK (context_length BETWEEN 0 AND 128),
    context BLOB NOT NULL CHECK (length(context) = 128),
    PRIMARY KEY (receiver_instance_id, diagnostic_sequence),
    FOREIGN KEY (receiver_instance_id) REFERENCES receiver_instances(receiver_instance_id),
    FOREIGN KEY (severity_id) REFERENCES diagnostic_severity_codes(id),
    FOREIGN KEY (error_domain_id) REFERENCES diagnostic_error_domain_codes(id),
    FOREIGN KEY (operation_id) REFERENCES diagnostic_operation_codes(id),
    FOREIGN KEY (error_domain_id, error_code_id) REFERENCES diagnostic_error_codes(error_domain_id, id),
    FOREIGN KEY (error_domain_id, context_schema_id) REFERENCES diagnostic_context_schemas(error_domain_id, id)
) STRICT, WITHOUT ROWID;

