CREATE TABLE quarantined_entities (
    quarantine_id BLOB NOT NULL CHECK (length(quarantine_id) = 32),
    entity_kind_id INTEGER NOT NULL,
    entity_schema_version INTEGER NOT NULL CHECK (entity_schema_version BETWEEN 0 AND 255),
    entity_length INTEGER NOT NULL CHECK (entity_length BETWEEN 2 AND 490),
    entity_bytes BLOB NOT NULL CHECK (length(entity_bytes) BETWEEN 2 AND 490),
    receiver_instance_id BLOB NOT NULL CHECK (length(receiver_instance_id) = 16),
    quarantined_at_monotonic_us INTEGER NOT NULL CHECK (quarantined_at_monotonic_us BETWEEN 0 AND 9223372036854775807),
    database_schema_version INTEGER NOT NULL CHECK (database_schema_version BETWEEN 1 AND 4294967295),
    failure_reason_id INTEGER NOT NULL,
    failure_operation_id INTEGER NOT NULL,
    sqlite_primary_code INTEGER CHECK (sqlite_primary_code IS NULL OR sqlite_primary_code BETWEEN -2147483648 AND 2147483647),
    sqlite_extended_code INTEGER CHECK (sqlite_extended_code IS NULL OR sqlite_extended_code BETWEEN -2147483648 AND 2147483647),
    os_errno INTEGER CHECK (os_errno IS NULL OR os_errno BETWEEN -2147483648 AND 2147483647),
    isolation_attempt_count INTEGER NOT NULL CHECK (isolation_attempt_count BETWEEN 1 AND 4294967295),
    CHECK (length(entity_bytes) = entity_length),
    PRIMARY KEY (quarantine_id),
    FOREIGN KEY (entity_kind_id) REFERENCES persist_queue_entity_kind_codes(id),
    FOREIGN KEY (receiver_instance_id) REFERENCES receiver_instances(receiver_instance_id),
    FOREIGN KEY (failure_reason_id) REFERENCES quarantine_failure_reason_codes(id),
    FOREIGN KEY (failure_operation_id) REFERENCES diagnostic_operation_codes(id)
) STRICT, WITHOUT ROWID;

