CREATE TABLE message_profiles (
    receiver_instance_id BLOB NOT NULL CHECK (length(receiver_instance_id) = 16),
    occurrence_sequence INTEGER NOT NULL CHECK (occurrence_sequence BETWEEN 0 AND 9223372036854775807),
    received_at_monotonic_us INTEGER NOT NULL CHECK (received_at_monotonic_us BETWEEN 0 AND 9223372036854775807),
    persist_queue_used_bytes_before_admission INTEGER NOT NULL CHECK (persist_queue_used_bytes_before_admission BETWEEN 0 AND 9223372036854775807),
    persist_queue_capacity_bytes INTEGER NOT NULL CHECK (persist_queue_capacity_bytes BETWEEN 0 AND 9223372036854775807),
    received_frame_length INTEGER CHECK (received_frame_length IS NULL OR received_frame_length BETWEEN 0 AND 255),
    received_frame BLOB CHECK (received_frame IS NULL OR length(received_frame) = 255),
    claimed_control INTEGER CHECK (claimed_control IS NULL OR claimed_control BETWEEN 0 AND 255),
    claimed_domain INTEGER CHECK (claimed_domain IS NULL OR claimed_domain BETWEEN 0 AND 255),
    claimed_node_id BLOB CHECK (claimed_node_id IS NULL OR length(claimed_node_id) = 8),
    claimed_message_id INTEGER CHECK (claimed_message_id IS NULL OR claimed_message_id BETWEEN 0 AND 4294967295),
    header_authenticated INTEGER NOT NULL CHECK (header_authenticated IN (0, 1)),
    decoded_sample_id INTEGER CHECK (decoded_sample_id IS NULL OR decoded_sample_id BETWEEN 0 AND 4294967295),
    rssi_dbm_x2 INTEGER CHECK (rssi_dbm_x2 IS NULL OR rssi_dbm_x2 BETWEEN -32768 AND 32767),
    snr_db_x4 INTEGER CHECK (snr_db_x4 IS NULL OR snr_db_x4 BETWEEN -32768 AND 32767),
    irq_status INTEGER CHECK (irq_status IS NULL OR irq_status BETWEEN 0 AND 65535),
    device_errors INTEGER CHECK (device_errors IS NULL OR device_errors BETWEEN 0 AND 65535),
    processing_result_id INTEGER NOT NULL,
    ack_selected_id INTEGER NOT NULL,
    ack_tx_result_id INTEGER NOT NULL,
    ack_frame BLOB CHECK (ack_frame IS NULL OR length(ack_frame) = 23),
    busy_wait_total_us INTEGER NOT NULL CHECK (busy_wait_total_us BETWEEN 0 AND 9223372036854775807),
    busy_wait_max_us INTEGER NOT NULL CHECK (busy_wait_max_us BETWEEN 0 AND 9223372036854775807),
    busy_wait_count INTEGER NOT NULL CHECK (busy_wait_count BETWEEN 0 AND 4294967295),
    busy_timeout_count INTEGER NOT NULL CHECK (busy_timeout_count BETWEEN 0 AND 4294967295),
    last_busy_timeout_opcode INTEGER CHECK (last_busy_timeout_opcode IS NULL OR last_busy_timeout_opcode BETWEEN 0 AND 255),
    t1_handler_started_monotonic_us INTEGER NOT NULL CHECK (t1_handler_started_monotonic_us BETWEEN 0 AND 9223372036854775807),
    t2_packet_copied_monotonic_us INTEGER CHECK (t2_packet_copied_monotonic_us IS NULL OR t2_packet_copied_monotonic_us BETWEEN 0 AND 9223372036854775807),
    t3_authentication_completed_monotonic_us INTEGER CHECK (t3_authentication_completed_monotonic_us IS NULL OR t3_authentication_completed_monotonic_us BETWEEN 0 AND 9223372036854775807),
    t4_set_tx_attempted_monotonic_us INTEGER CHECK (t4_set_tx_attempted_monotonic_us IS NULL OR t4_set_tx_attempted_monotonic_us BETWEEN 0 AND 9223372036854775807),
    t5_tx_done_monotonic_us INTEGER CHECK (t5_tx_done_monotonic_us IS NULL OR t5_tx_done_monotonic_us BETWEEN 0 AND 9223372036854775807),
    t6_set_rx_issued_monotonic_us INTEGER CHECK (t6_set_rx_issued_monotonic_us IS NULL OR t6_set_rx_issued_monotonic_us BETWEEN 0 AND 9223372036854775807),
    persistence_classification_id INTEGER NOT NULL,
    PRIMARY KEY (receiver_instance_id, occurrence_sequence),
    FOREIGN KEY (receiver_instance_id) REFERENCES receiver_instances(receiver_instance_id),
    FOREIGN KEY (processing_result_id) REFERENCES processing_result_codes(id),
    FOREIGN KEY (ack_selected_id) REFERENCES ack_selection_codes(id),
    FOREIGN KEY (ack_tx_result_id) REFERENCES ack_tx_result_codes(id),
    FOREIGN KEY (persistence_classification_id) REFERENCES persistence_classification_codes(id)
) STRICT, WITHOUT ROWID;

