BEFORE UPDATE ON message_profiles
BEGIN
    SELECT RAISE(ABORT, 'message_profiles is append-only');
END;

CREATE TRIGGER message_profiles_no_delete
BEFORE DELETE ON message_profiles
BEGIN
    SELECT RAISE(ABORT, 'message_profiles is append-only');
END;

CREATE TABLE reading_messages (
    node_id BLOB NOT NULL CHECK (length(node_id) = 8),
    message_id INTEGER NOT NULL CHECK (message_id BETWEEN 0 AND 4294967295),
    sample_id INTEGER NOT NULL CHECK (sample_id BETWEEN 0 AND 4294967295),
    reading_body BLOB NOT NULL CHECK (length(reading_body) = 32),
    is_canonical_for_sample INTEGER NOT NULL CHECK (is_canonical_for_sample IN (0, 1)),
    run_ms INTEGER NOT NULL CHECK (run_ms BETWEEN 0 AND 65535),
    soil_0_mv INTEGER NOT NULL CHECK (soil_0_mv BETWEEN 0 AND 65535),
    soil_1_mv INTEGER NOT NULL CHECK (soil_1_mv BETWEEN 0 AND 65535),
    soil_temp_0_centi_c INTEGER NOT NULL CHECK (soil_temp_0_centi_c BETWEEN -32768 AND 32767),
    soil_temp_1_centi_c INTEGER NOT NULL CHECK (soil_temp_1_centi_c BETWEEN -32768 AND 32767),
    enclosure_centi_c INTEGER NOT NULL CHECK (enclosure_centi_c BETWEEN -32768 AND 32767),
    enclosure_pressure_pa INTEGER NOT NULL CHECK (enclosure_pressure_pa BETWEEN 0 AND 4294967295),
    enclosure_humidity_centi_pct INTEGER NOT NULL CHECK (enclosure_humidity_centi_pct BETWEEN 0 AND 65535),
    reset_reason INTEGER NOT NULL CHECK (reset_reason BETWEEN 0 AND 255),
    previous_current_tx_attempts INTEGER NOT NULL CHECK (previous_current_tx_attempts BETWEEN 0 AND 255),
    previous_awake_ms INTEGER NOT NULL CHECK (previous_awake_ms BETWEEN 0 AND 65535),
    previous_current_delivery_ms INTEGER NOT NULL CHECK (previous_current_delivery_ms BETWEEN 0 AND 65535),
    previous_cycle_tx_attempts INTEGER NOT NULL CHECK (previous_cycle_tx_attempts BETWEEN 0 AND 255),
    previous_cycle_accepted_readings INTEGER NOT NULL CHECK (previous_cycle_accepted_readings BETWEEN 0 AND 255),
    flags INTEGER NOT NULL CHECK (flags BETWEEN 0 AND 65535),
    first_receiver_instance_id BLOB NOT NULL CHECK (length(first_receiver_instance_id) = 16),
    first_occurrence_sequence INTEGER NOT NULL CHECK (first_occurrence_sequence BETWEEN 0 AND 9223372036854775807),
    PRIMARY KEY (node_id, message_id),
    FOREIGN KEY (first_receiver_instance_id, first_occurrence_sequence) REFERENCES message_profiles(receiver_instance_id, occurrence_sequence)
) STRICT, WITHOUT ROWID;

CREATE UNIQUE INDEX reading_messages_one_canonical_sample
ON reading_messages (node_id, sample_id)
WHERE is_canonical_for_sample = 1;

CREATE TRIGGER reading_messages_no_update
BEFORE UPDATE ON reading_messages
BEGIN
    SELECT RAISE(ABORT, 'reading_messages is append-only');
END;

CREATE TRIGGER reading_messages_no_delete
BEFORE DELETE ON reading_messages
BEGIN
    SELECT RAISE(ABORT, 'reading_messages is append-only');
END;

CREATE TABLE communicator_state (
    singleton_id INTEGER NOT NULL CHECK (singleton_id = 1),
    state_format_version INTEGER NOT NULL CHECK (state_format_version = 1),
    generation INTEGER NOT NULL CHECK (generation BETWEEN 1 AND 9223372036854775807),
    state_blob BLOB NOT NULL,
    state_sha256 BLOB NOT NULL CHECK (length(state_sha256) = 32),
    PRIMARY KEY (singleton_id)
) STRICT;
